#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int r,c,nr,nc;scanf("%d %d %d %d",&r,&c,&nr,&nc);
vector<long long>f;f.reserve(r*c);
for(int i=0;i<r;++i)for(int j=0;j<c;++j){long long x;scanf("%lld",&x);f.push_back(x);}
if(r*c!=nr*nc){printf("NO\n");return 0;}
printf("YES\n");
for(int i=0;i<nr;++i){for(int j=0;j<nc;++j){if(j)printf(" ");printf("%lld",f[i*nc+j]);}printf("\n");}
return 0;}

